using System.Linq;using System.Web.Mvc;using MaSV_LTW_MyStore.Models; namespace MaSV_LTW_MyStore.Areas.Admin.Controllers { public class CategoriesController:Controller { StoreContext db=new StoreContext(); protected override void OnActionExecuting(ActionExecutingContext c){if(Session["Role"]==null||Session["Role"].ToString()!="A"){c.Result=RedirectToAction("Login","Account",new{area=""});return;}base.OnActionExecuting(c);} public ActionResult Index(){return View(db.Categories.OrderBy(x=>x.CategoryName).ToList());} public ActionResult Create(){return View("Form",new Category());} [HttpPost,ValidateAntiForgeryToken] public ActionResult Create(Category x){if(ModelState.IsValid){db.Categories.Add(x);db.SaveChanges();return RedirectToAction("Index");}return View("Form",x);} public ActionResult Edit(int id){var x=db.Categories.Find(id);return x==null?(ActionResult)HttpNotFound():View("Form",x);} [HttpPost,ValidateAntiForgeryToken] public ActionResult Edit(Category x){if(ModelState.IsValid){db.Entry(x).State=System.Data.Entity.EntityState.Modified;db.SaveChanges();return RedirectToAction("Index");}return View("Form",x);} public ActionResult Delete(int id){var x=db.Categories.Find(id);if(x!=null){if(db.Products.Any(p=>p.CategoryID==id)){TempData["Error"]="Danh mục đang có sản phẩm, không thể xóa.";}else{db.Categories.Remove(x);db.SaveChanges();}}return RedirectToAction("Index");} } }